'use strict';

/**
* Return the index of the first falsy element in a double-precision complex floating-point strided array.
*
* @module @stdlib/blas/ext/base/zindex-of-falsy
*
* @example
* import Complex128Array from '@stdlib/array/complex128';
* import zindexOfFalsy from '@stdlib/blas/ext/base/zindex-of-falsy';
*
* var x = new Complex128Array( [ 1.0, 2.0, 0.0, 0.0, 4.0, 5.0 ] );
*
* var idx = zindexOfFalsy( x.length, x, 1 );
* // returns 1
*
* @example
* import Complex128Array from '@stdlib/array/complex128';
* import zindexOfFalsy from '@stdlib/blas/ext/base/zindex-of-falsy';
*
* var x = new Complex128Array( [ 1.0, 2.0, 0.0, 0.0, 4.0, 5.0 ] );
*
* var idx = zindexOfFalsy.ndarray( x.length, x, 1, 0 );
* // returns 1
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var zindexOfFalsy;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	zindexOfFalsy = main;
} else {
	zindexOfFalsy = tmp;
}


// EXPORTS //

export default zindexOfFalsy;

// exports: { "ndarray": "zindexOfFalsy.ndarray" }
