'use strict';

/**
* Return the index of the first falsy element in a single-precision floating-point strided array.
*
* @module @stdlib/blas/ext/base/sindex-of-falsy
*
* @example
* import Float32Array from '@stdlib/array/float32';
* import sindexOfFalsy from '@stdlib/blas/ext/base/sindex-of-falsy';
*
* var x = new Float32Array( [ 1.0, 2.0, 0.0, 3.0, 4.0, 5.0, 6.0, 7.0 ] );
*
* var idx = sindexOfFalsy( x.length, x, 1 );
* // returns 2
*
* @example
* import Float32Array from '@stdlib/array/float32';
* import sindexOfFalsy from '@stdlib/blas/ext/base/sindex-of-falsy';
*
* var x = new Float32Array( [ 1.0, 2.0, 0.0, 3.0, 4.0, 5.0, 6.0, 7.0 ] );
*
* var idx = sindexOfFalsy.ndarray( x.length, x, 1, 0 );
* // returns 2
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils/try-require';
import isError from '@stdlib/assert/is-error';
import main from './main.js';


// MAIN //

var sindexOfFalsy;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	sindexOfFalsy = main;
} else {
	sindexOfFalsy = tmp;
}


// EXPORTS //

export default sindexOfFalsy;

// exports: { "ndarray": "sindexOfFalsy.ndarray" }
